import {createEconomy,cleanEconomyEdits,ECONOMY_FORMAT,money} from './economy-core.js?v=43.1';
import {simulateEconomy,cleanEconomyState} from './economy-simulation.js?v=43.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:2});
export async function createEconomyUI({D,provinces,provinceAt,title,toast,beforeOpen,selectCity,onUpdate=()=>{}}){
 const response=await fetch('./economy-source.json?v=32',{cache:'no-store'});if(!response.ok)throw Error('Dados econômicos indisponíveis.');const data=await response.json(),key='silvengard-economy-v1-'+(D.savedDefaults?.id||'base');
 let edits=cleanEconomyEdits(D.economyEdits||{format:ECONOMY_FORMAT},D,data),state=cleanEconomyState(D.economyState,data),previousState=null,dialog=null,scope='city-23',tab='summary',editing=false;
 try{const local=localStorage.getItem(key);if(local)edits=cleanEconomyEdits(JSON.parse(local),D,data);}catch(e){toast(e.message);}
 try{const local=localStorage.getItem(key+'-state');if(local)state=cleanEconomyState(JSON.parse(local),data);}catch(e){toast(e.message);}
 function persistState(next){state=cleanEconomyState(next,data);try{localStorage.setItem(key+'-state',JSON.stringify(state));}catch{toast('Exporte a edição para guardar os ciclos econômicos.');}onUpdate();render();}
 function persist(next){edits=cleanEconomyEdits(next,D,data);try{localStorage.setItem(key,JSON.stringify(edits));}catch{toast('Exporte a edição para guardar a economia.');}onUpdate();render();}
 const cityName=id=>{const b=D.cities.find(c=>c.i===id);return b?title(b):'—';};
 function close(){dialog?.remove();dialog=null;}
 function render(){
  if(!dialog)return;const model=createEconomy(D,data,edits),[kind,rawId]=scope.split('-'),id=+rawId,b=D.cities.find(b=>b.i===id),p=provinces().find(p=>p.i===id),report=kind==='province'?model.province(id,provinceAt):b?model.city(b):null;
  const heading=kind==='province'?p?.name:b?title(b):'Economia',goods=[...model.goods.values()].filter(g=>!g.inactive).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  dialog.innerHTML=`<header class="econHeading"><div><small>PRODUÇÃO E COMÉRCIO</small><h2>Economia de Silvengard</h2></div><button id="closeEconomy" aria-label="Fechar economia">✕</button></header><div class="econBody"><div class="econTabs"><button data-econtab="summary" class="${tab==='summary'?'active':''}">Produção e comércio</button><button data-econtab="simulation" class="${tab==='simulation'?'active':''}">Ciclos e estoques</button><button data-econtab="goods" class="${tab==='goods'?'active':''}">Bens e preços</button><button data-econtab="settings" class="${tab==='settings'?'active':''}">Ajustes</button></div><p class="econCurrency">1 PO = 10 PP = 100 PC · 1 PL = 10 PO</p><p class="muted">Ciclo de ${edits.cycleDays} dias · capacidades e preços iniciais ajustáveis. Os valores são referências de produção, sem avanço automático do tempo ou crédito ao tesouro.</p><div id="econContent"></div></div>`;
  const $=s=>dialog.querySelector(s);$('#closeEconomy').onclick=close;for(const t of dialog.querySelectorAll('[data-econtab]'))t.onclick=()=>{tab=t.dataset.econtab;editing=false;render();};
  if(tab==='simulation'){
   const names=id=>{const [kind,key]=id.split(':');return kind==='carrier'?'Transportadores · '+(D.states.find(s=>s.i===+key)?.name.trim()||key):kind==='service'?'Serviços · '+cityName(+key):kind==='state'?'Alfândega · '+(D.states.find(s=>s.i===+key)?.name.trim()||key):kind==='city'?cityName(+key):provinces().find(p=>p.i===+key)?.name||'Província '+key;},last=state.last,summary=state.history.at(-1);
   $('#econContent').innerHTML=`<h3>Ciclos, estoques e comércio mundial</h3><p>O ciclo é aplicado a todas as cidades e províncias. Recursos entram nos estoques; oficinas compram insumos disponíveis e produzem conforme sua capacidade. As localidades consomem alimentos, utilidades, materiais de construção, equipamento e luxo. O consumo urbano acompanha a população; as pessoas do entorno rural já estão incluídas na população das localidades.</p><p class="muted">Entregas usam preços por escassez, relações diplomáticas, embargos, tarifas, bloqueios e risco de pirataria, além das rotas cadastradas. O frete terrestre e o marítimo são configuráveis, recebidos por transportadores; compras entre estados em guerra e trânsito terrestre por território inimigo são bloqueados. Sem estoque, caixa ou acesso, a compra não ocorre. As moedas são transferidas entre contas, sem crédito automático pelo valor bruto produzido.</p><div class="econMetrics"><span><b>${state.cycle}</b>Ciclos aplicados</span><span><b>${money(Object.values(state.accounts).reduce((s,a)=>s+a.coins,0)/100)}</b>Caixa total nas contas</span><span><b>${summary?.trades||0}</b>Transações no último ciclo</span></div><button id="runEconCycle">Aplicar próximo ciclo ao mundo</button><button id="undoEconCycle" ${previousState?'':'disabled'}>Desfazer último ciclo</button><button id="resetEconCycle">Reiniciar simulação</button>${summary?`<p>Comércio no ciclo: <b>${money(summary.tradeValue)}</b> · demanda alimentar ainda não atendida: <b>${num(summary.unmetFood)}</b> unidades de cobertura.</p>`:''}<p class="econNotice">Tarifas arrecadadas no ciclo: <b>${money(summary?.tariffs||0)}</b> · valor de referência das perdas por pirataria: <b>${money(summary?.lostValue||0)}</b>. Tarifas são creditadas às contas Alfândega de cada estado.</p><details><summary>Cargas em trânsito · ${state.shipments.length}</summary>${state.shipments.map(t=>`<p>${esc(names(t.from))} → ${esc(names(t.to))}: ${num(t.units)} ${esc(model.goods.get(t.good)?.name)} · chegada em ${num(Math.max(0,t.arrivalDay-state.elapsedDays))} dias${t.hold?' · retida por '+esc(({war:'guerra',embargo:'embargo',blockade:'bloqueio naval',destination:'destino indisponível'})[t.hold]):''}</p>`).join('')||'<p>Nenhuma carga pendente.</p>'}</details><p>Frete e serviços no ciclo: ${money(summary?.services||0)} em transferências, incluindo salários de transportadores e prestadores. Esses valores não são somados à produção de bens.</p><h4>Caixa e estoques por localidade</h4><div class="econTableWrap"><table><thead><tr><th>Localidade / mercado rural</th><th>Caixa</th><th>Estoques</th><th>Pendências</th></tr></thead><tbody>${Object.entries(state.accounts).sort((a,b)=>names(a[0]).localeCompare(names(b[0]),'pt-BR')).map(([id,a])=>`<tr><td>${esc(names(id))}</td><td>${money(a.coins/100)}</td><td>${Object.entries(a.stock).filter(([g,n])=>n>.001).map(([g,n])=>esc(model.goods.get(+g)?.name)+': '+num(n)).join(' · ')||'—'}${Object.keys(a.assets||{}).length?'<small>Instalado: '+Object.entries(a.assets).map(([g,n])=>esc(model.goods.get(+g)?.name)+': '+num(n)).join(' · ')+'</small>':''}</td><td>${last?.demand?.[id]?Object.entries(last.demand[id]).filter(([g,n])=>n>.001).map(([g,n])=>esc(({food:'Alimentos',utilities:'Utilidades',construction:'Construção',military:'Equipamento',luxury:'Luxo',research:'Pesquisa arcana',fleet:'Frota marítima',inlandFleet:'Frota fluvial/lacustre',armor:'Armaduras'})[g]||g)+': '+num(n)).join(' · ')||'Demanda atendida':'—'}${last?.idle?.[id]?'<small>Capacidade ociosa: '+Object.entries(last.idle[id]).filter(([g,n])=>n>.001).map(([g,n])=>esc(model.goods.get(+g)?.name)+': '+num(n)).join(' · ')+'</small>':''}</td></tr>`).join('')}</tbody></table></div><h4>Transações do último ciclo</h4><div class="econTableWrap"><table><thead><tr><th>Fornecedor → comprador</th><th>Bem</th><th>Quantidade</th><th>Pagamento</th></tr></thead><tbody>${(last?.trades||[]).map(t=>`<tr><td>${esc(names(t.from))} → ${esc(names(t.to))}</td><td>${esc(model.goods.get(t.good)?.name)}</td><td>${num(t.units)}</td><td>${money(t.coins/100)}</td></tr>`).join('')}</tbody></table></div><p class="muted">O caixa inicial é atribuído uma vez a cada localidade, conforme a liquidez familiar inicial configurada. Valores e estoques são da simulação do cenário. Valar e cidades desabitadas não participam. Produção limitada por insumos aparece como capacidade não utilizada; não são criados produtos sem consumi-los.</p>`;
   $('#runEconCycle').onclick=()=>{try{$('#runEconCycle').disabled=true;const next=simulateEconomy(D,data,edits,state,provinces(),provinceAt);previousState=structuredClone(state);persistState(next);toast('Ciclo mundial aplicado');}catch(e){toast(e.message);render();}};
   $('#undoEconCycle').onclick=()=>{if(previousState){const old=previousState;previousState=null;persistState(old);}};$('#resetEconCycle').onclick=()=>{previousState=structuredClone(state);persistState(null);};return;
  }
  if(tab==='goods'){
   $('#econContent').innerHTML='<h3>Bens e preços em peças de ouro</h3><p class="muted">Preço por unidade comercial indicada. Lavanthir vale mais que ossos de dragão, e ossos de dragão mais que ferro. Pesos e cobertura alimentar são referências de calibração do cenário; a ficha de cada bem mostra suas unidades.</p><div class="econTableWrap"><table><thead><tr><th>Bem</th><th>Unidade</th><th>Preço em PO</th></tr></thead><tbody>'+goods.map(g=>`<tr><td>${esc(g.name)}</td><td>${esc(g.unit)}</td><td><input aria-label="Preço de ${esc(g.name)}" data-price="${g.i}" type="number" min="0" max="1000000000" step="0.01" value="${model.price(g.i)}"></td></tr>`).join('')+'</tbody></table></div><button id="saveEconPrices">Salvar preços</button><button id="resetEconPrices">Restaurar preços de referência</button>';
   $('#saveEconPrices').onclick=()=>{try{const prices={};for(const input of dialog.querySelectorAll('[data-price]')){if(!input.value.trim())throw Error('Preencha todos os preços.');prices[input.dataset.price]=Number(input.value);}persist({...edits,prices});toast('Preços salvos');}catch(e){toast(e.message);}};
   $('#resetEconPrices').onclick=()=>persist({...edits,prices:{}});return;
  }
  if(tab==='settings'){
   $('#econContent').innerHTML=`<h3>Economia e transporte</h3><p>Os preços dos mercados variam por região. Os preços-base podem ser ajustados em Bens e preços.</p><label>Frete terrestre · % do preço por km<input id="econLandFreight" type="number" min="0" max="10" step="0.001" value="${edits.landFreight*100}"></label><label>Frete marítimo · % do preço por km<input id="econSeaFreight" type="number" min="0" max="10" step="0.001" value="${edits.seaFreight*100}"></label><label>Dias por ciclo<input id="econCycle" type="number" min="1" max="365" value="${edits.cycleDays}"></label><label>Multiplicador da produção rural<input id="econRural" type="number" min="0" max="100" step="0.1" value="${edits.ruralScale}"></label><label>Consumo alimentar por 1.000 habitantes / 30 dias<input id="econFood" type="number" min="0" max="100" step="0.1" value="${edits.foodPer1000}"></label><label>${data.calibration?.useSocialLiquidity?'Multiplicador do capital de giro social':'Caixa inicial por habitante · PO'}<input id="econCapital" type="number" min="0" max="10000" step="0.1" value="${edits.initialGoldPerResident}"></label><p class="muted">O caixa inicial vale para novas contas ou após reiniciar a simulação. Os estoques começam vazios; a produção e as compras os abastecem. As capacidades urbanas são calibradas para 30 dias; o ciclo escolhido escala os volumes. Você pode editar a capacidade de cada cidade em Produção e comércio.</p><p class="muted">Valar permanece sem atividade. Adhuc Vivere não produz alimentos nem extrai recursos rurais. Localidades sem habitantes não produzem.</p><button id="saveEconSettings">Salvar ajustes</button>`;
   $('#saveEconSettings').onclick=()=>{try{persist({...edits,landFreight:Number($('#econLandFreight').value)/100,seaFreight:Number($('#econSeaFreight').value)/100,cycleDays:Number($('#econCycle').value),ruralScale:Number($('#econRural').value),foodPer1000:Number($('#econFood').value),initialGoldPerResident:Number($('#econCapital').value)});toast('Ajustes salvos');}catch(e){toast(e.message);}};return;
  }
  const options='<optgroup label="Cidades">'+[...D.cities].sort((a,b)=>title(a).localeCompare(title(b),'pt-BR')).map(b=>`<option value="city-${b.i}" ${scope==='city-'+b.i?'selected':''}>${esc(title(b))} · ${esc(D.states.find(s=>s.i===b.state)?.name.trim())}</option>`).join('')+'</optgroup><optgroup label="Províncias">'+[...provinces()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(p=>`<option value="province-${p.i}" ${scope==='province-'+p.i?'selected':''}>${esc(p.name)} · ${esc(D.states.find(s=>s.i===p.state)?.name.trim())}</option>`).join('')+'</optgroup>';
  $('#econContent').innerHTML=`<label>Consultar cidade ou província<select id="economyScope" aria-label="Consultar cidade ou província">${options}</select></label><h3>${esc(heading)}</h3><div id="econReport"></div>`;$('#economyScope').onchange=e=>{scope=e.target.value;editing=false;render();};if(!report){$('#econReport').textContent='Localidade não encontrada.';return;}
  const rows=[...report.production].sort((a,b)=>a[0]-b[0]),inputRows=[...report.inputs].sort((a,b)=>a[0]-b[0]),table=(items,production)=>'<div class="econTableWrap"><table><thead><tr><th>Bem</th><th>Volume / ciclo</th><th>Valor de referência</th></tr></thead><tbody>'+items.map(([id,n])=>`<tr><td>${esc(model.goods.get(id)?.name||id)}${production&&report.rural?.has(id)?'<small>Inclui produção rural</small>':''}</td><td>${num(n)} ${esc(model.goods.get(id)?.unit||'')}</td><td>${money(n*model.price(id))}</td></tr>`).join('')+'</tbody></table></div>';
  const connections=model.connections(report.cities.map(b=>b.i));
  $('#econReport').innerHTML=`<p>${esc(report.note)}</p><div class="econMetrics"><span><b>${money(report.gross)}</b>Valor bruto potencial / ciclo</span><span><b>${money(report.inputCost)}</b>Insumos de fabricação listados</span></div>${report.incompleteCost?'<p class="econNotice">A composição da liga Lavanthir ainda não foi definida. Os custos de seus componentes não estão calculados.</p>':''}<h4>Produção</h4>${rows.length?table(rows,true):'<p class="muted">Sem produção ativa.</p>'}${kind==='city'?'<button id="editCityEconomy">Editar capacidade produtiva</button>':''}<div id="econProductionEdit"></div><h4>Insumos de fabricação</h4>${inputRows.length?table(inputRows,false):'<p class="muted">Sem insumos de fabricação registrados.</p>'}<h4>Saldo produtivo</h4><p class="muted">Produção menos insumos de fabricação. Ainda não desconta consumo da população, transporte, salários ou impostos; não é lucro nem estoque.</p>${model.balance(report).map(r=>`<div class="fact"><span>${esc(model.goods.get(r.id)?.name)}</span><b>${r.balance<0?'Necessita '+num(-r.balance):'Disponível '+num(r.balance)} ${esc(model.goods.get(r.id)?.unit)}</b></div>`).join('')}<h4>Conexões comerciais existentes</h4>${connections.map(r=>`<p class="econRoute"><b>${esc(r.name)}</b><small>${r.kind==='sea'?'Marítima':r.kind==='mixed'?'Híbrida':'Terrestre'}${r.partners.length?' · '+r.partners.map(i=>esc(cityName(i))).join(', '):''}</small></p>`).join('')||'<p class="muted">Sem conexão comercial registrada.</p>'}${kind==='province'?'<h4>Cidades incluídas</h4>'+report.cities.map(b=>`<button class="provinceTown" data-econcity="${b.i}">${esc(title(b))} ↗</button>`).join(''):''}<p class="muted">As conexões mostram acesso por rotas cadastradas. As transações e os estoques antigos não são tratados como comércio atual. A produção provincial reúne as cidades e os recursos rurais uma única vez.</p>`;
  for(const link of dialog.querySelectorAll('[data-econcity]'))link.onclick=()=>{scope='city-'+link.dataset.econcity;render();};
  if(kind==='city')$('#editCityEconomy').onclick=()=>{editing=!editing;if(!editing){render();return;}const values=new Map(rows.map(([id,n])=>[id,n/(edits.cycleDays/30)]));for(const [g,n]of Object.entries(edits.cityProduction[b.i]||{}))values.set(+g,n);$('#econProductionEdit').innerHTML='<h4>Capacidade por 30 dias</h4><p class="muted">Zero desativa um produto. A escolha não modifica população, cultura ou religião.</p>'+[...values].map(([id,n])=>`<label>${esc(model.goods.get(id)?.name)} · ${esc(model.goods.get(id)?.unit)}<input data-capacity="${id}" type="number" min="0" max="1000000000" step="0.01" value="${+n.toFixed(4)}"></label>`).join('')+`<label>Adicionar produto<select id="addEconGood">${goods.filter(g=>!values.has(g.i)).map(g=>`<option value="${g.i}">${esc(g.name)}</option>`).join('')}</select></label><button id="addEconCapacity">Adicionar produto</button><button id="saveCityEconomy">Salvar capacidade</button>`;
   $('#addEconCapacity').onclick=()=>{const id=+$('#addEconGood').value;if(!id||dialog.querySelector(`[data-capacity="${id}"]`))return;$('#saveCityEconomy').insertAdjacentHTML('beforebegin',`<label>${esc(model.goods.get(id)?.name)}<input data-capacity="${id}" type="number" min="0" max="1000000000" step="0.01" value="1"></label>`);};
   $('#saveCityEconomy').onclick=()=>{try{const capacities={};for(const input of dialog.querySelectorAll('[data-capacity]')){if(!input.value.trim())throw Error('Informe as quantidades.');capacities[input.dataset.capacity]=Number(input.value);}persist({...edits,cityProduction:{...edits.cityProduction,[b.i]:capacities}});toast('Capacidades salvas');}catch(e){toast(e.message);}};
  };
 }
 function open(target={}){beforeOpen();close();scope=target.provinceId?'province-'+target.provinceId:'city-'+(target.cityId||23);tab=target.tab||'summary';editing=false;dialog=document.createElement('dialog');dialog.className='economyDialog';document.body.append(dialog);dialog.addEventListener('cancel',close);render();dialog.showModal();}
 return {open,close,exportData:()=>structuredClone(edits),exportState:()=>structuredClone(state),validateState:raw=>cleanEconomyState(raw,data),validate:raw=>cleanEconomyEdits(raw,D,data),importState:raw=>persistState(raw),importData(raw){persist(raw);}};
}
